package com.printflow.customer;

import com.printflow.identity.*;
import jakarta.validation.constraints.*;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;

/** Manual verified receipts only. No gateway or tax-registration claim. All writes lock the enquiry. */
@Service public class Payments {
 public record Policy(@NotNull UUID quoteId,@Min(0) int expectedRevision,@Min(0) @Max(100000000000L) long advancePaise,LocalDate creditDue,@NotBlank @Size(min=10,max=1000) String reason){}
 public record Receipt(@NotNull UUID id,@NotNull UUID quoteId,@Min(1) @Max(100000000000L) long amountPaise,@NotBlank @Pattern(regexp="CASH|UPI|BANK|CARD|CHEQUE") String method,@NotBlank @Size(min=3,max=200) String reference,@NotNull @PastOrPresent LocalDate paidOn,@AssertTrue boolean verified){}
 public record Reverse(@NotBlank @Size(min=10,max=1000) String reason){}
 public record Issue(@NotNull UUID quoteId){}
 private final boolean production;private final JdbcTemplate db;private final ProjectNotifications mail;private final InvoicePdf pdf;private final JsonMapper json;
 public Payments(JdbcTemplate db,ProjectNotifications mail,InvoicePdf pdf,JsonMapper json,org.springframework.core.env.Environment env){this.production=env.matchesProfiles("prod");this.db=db;this.mail=mail;this.pdf=pdf;this.json=json;}
 private ResponseStatusException conflict(String s){return new ResponseStatusException(HttpStatus.CONFLICT,s);}
 private Map<String,Object> scope(StaffPrincipal u,UUID id,boolean write){
  if(write&&!u.role().equals("OWNER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the owner may confirm finances");
  var rows=db.queryForList("select customer_user_id,assigned_staff_id,status,customer_name,email from enquiries where id=?"+(write?" for update":""),id);if(rows.isEmpty())throw new NoSuchElementException();var e=rows.getFirst();
  if(!u.role().equals("OWNER")&&!(u.role().equals("CUSTOMER")&&u.id().equals(e.get("customer_user_id")))&&!(u.role().equals("SALES")&&u.id().equals(e.get("assigned_staff_id"))))throw new NoSuchElementException();return e;
 }
 private Map<String,Object> quote(UUID id){var q=db.queryForList("select id,version,total_paise,scope,terms,line_items::text as line_items from quote_versions where enquiry_id=? and state='ACCEPTED'",id);if(q.isEmpty())throw conflict("Accept a quotation before configuring payments");return q.getFirst();}
 private void current(Map<String,Object> q,UUID expected){if(!q.get("id").equals(expected))throw conflict("The accepted quotation changed; refresh finances first");}
 private Map<String,Object> policy(UUID id){var p=db.queryForList("select id,quote_id,revision,advance_paise,to_char(credit_due,'YYYY-MM-DD') as credit_due,reason,created_at from payment_policies where enquiry_id=? order by revision desc limit 1",id);return p.isEmpty()?null:p.getFirst();}
 long paid(UUID id){return db.queryForObject("select coalesce(sum(r.amount_paise),0)::bigint from payment_receipts r where r.enquiry_id=? and (?=false or r.method<>'RAZORPAY_TEST') and not exists(select 1 from payment_reversals v where v.receipt_id=r.id)",Long.class,id,production);}
 static long amount(Map<String,Object> m,String key){return ((Number)m.get(key)).longValue();}
 private boolean valid(Map<String,Object> q,Map<String,Object> p){return p!=null&&q.get("id").equals(p.get("quote_id"));}
 private boolean credit(Map<String,Object> p){return p!=null&&p.get("credit_due")!=null&&!LocalDate.parse(p.get("credit_due").toString()).isBefore(LocalDate.now(ZoneId.of("Asia/Kolkata")));}
 public String stageCode(UUID id){return stageCodes(List.of(id)).getOrDefault(id,"AWAITING_QUOTATION");}
 public Map<UUID,String> stageCodes(Collection<UUID> enquiries){if(enquiries.isEmpty())return Map.of();String marks=String.join(",",Collections.nCopies(enquiries.size(),"?"));String sql="select q.enquiry_id,q.id as quote_id,q.total_paise,coalesce(r.received,0)::bigint as received,p.quote_id as policy_quote,p.advance_paise,p.credit_due from quote_versions q left join lateral(select coalesce(sum(x.amount_paise),0)::bigint as received from payment_receipts x where x.enquiry_id=q.enquiry_id and (?=false or x.method<>'RAZORPAY_TEST') and not exists(select 1 from payment_reversals v where v.receipt_id=x.id)) r on true left join lateral(select quote_id,advance_paise,credit_due from payment_policies where enquiry_id=q.enquiry_id order by revision desc limit 1) p on true where q.state='ACCEPTED' and q.enquiry_id in ("+marks+")";var args=new ArrayList<Object>();args.add(production);args.addAll(enquiries);var result=new LinkedHashMap<UUID,String>();for(var row:db.queryForList(sql,args.toArray())){UUID id=(UUID)row.get("enquiry_id");long received=amount(row,"received"),total=amount(row,"total_paise");String code;if(!row.get("quote_id").equals(row.get("policy_quote")))code="TERMS_PENDING";else if(received>total)code="OVERPAID";else if(received==total)code="PAID_IN_FULL";else if(received<amount(row,"advance_paise"))code="ADVANCE_DUE";else{Object due=row.get("credit_due");code=due!=null&&!LocalDate.parse(due.toString()).isBefore(LocalDate.now(ZoneId.of("Asia/Kolkata")))?"BALANCE_ON_CREDIT":"BALANCE_DUE";}result.put(id,code);}return result;}
 public String stage(UUID id){return switch(stageCode(id)){case "AWAITING_QUOTATION"->"Awaiting quotation acceptance";case "OVERPAID"->"Overpaid \u2014 owner reconciliation needed";case "PAID_IN_FULL"->"Paid in full";case "TERMS_PENDING"->"Payment terms pending";case "ADVANCE_DUE"->"Advance payment due";case "BALANCE_ON_CREDIT"->"Balance on approved credit";default->"Advance satisfied \u2014 balance due";};}
 @Transactional(readOnly=true) public Map<String,Object> view(StaffPrincipal u,UUID id){var e=scope(u,id,false);var q=quote(id);var p=policy(id);long total=amount(q,"total_paise"),received=paid(id);var result=new LinkedHashMap<String,Object>();result.put("quoteId",q.get("id"));result.put("quoteVersion",q.get("version"));result.put("totalPaise",total);result.put("paidPaise",received);result.put("balancePaise",Math.max(0,total-received));result.put("overpaidPaise",Math.max(0,received-total));result.put("policy",p);result.put("policyCurrent",valid(q,p));result.put("owner",u.role().equals("OWNER"));result.put("customer",u.role().equals("CUSTOMER"));result.put("closed","CLOSED".equals(e.get("status")));result.put("released",db.queryForObject("select exists(select 1 from fulfilment_work where enquiry_id=?)",Boolean.class,id));result.put("stage",stage(id));result.put("receipts",db.queryForList("select r.id,r.receipt_number,r.amount_paise,r.method,r.reference,to_char(r.paid_on,'YYYY-MM-DD') as paid_on,v.reason as reversal_reason from payment_receipts r left join payment_reversals v on v.receipt_id=r.id where r.enquiry_id=? order by r.created_at desc",id));result.put("invoices",db.queryForList("select id,quote_id,invoice_number,to_char(issued_on,'YYYY-MM-DD') as issued_on,total_paise from finance_invoices where enquiry_id=? order by invoice_number desc",id));return result;}
 @Transactional public Map<String,Object> configure(StaffPrincipal u,UUID id,Policy input){var e=scope(u,id,true);var q=quote(id);current(q,input.quoteId());var p=policy(id);if("CLOSED".equals(e.get("status")))throw conflict("Closed payment terms cannot be changed");if(db.queryForObject("select exists(select 1 from fulfilment_work where enquiry_id=?)",Boolean.class,id))throw conflict("Payment rules cannot change after production release");if(db.queryForObject("select exists(select 1 from finance_invoices where enquiry_id=?)",Boolean.class,id))throw conflict("Issued invoice payment terms are immutable");if(input.expectedRevision()!=(p==null?0:amount(p,"revision")))throw conflict("Payment terms changed; refresh first");if(input.advancePaise()>amount(q,"total_paise"))throw conflict("Advance cannot exceed the accepted total");if(input.reason().trim().length()<10)throw new IllegalArgumentException("Explain the payment agreement");if(input.creditDue()!=null&&input.creditDue().isBefore(LocalDate.now(ZoneId.of("Asia/Kolkata"))))throw conflict("Credit due date cannot be in the past");UUID event=UUID.randomUUID();db.update("insert into payment_policies(id,enquiry_id,quote_id,revision,advance_paise,credit_due,reason,actor_id) values(?,?,?,?,?,?,?,?)",event,id,input.quoteId(),input.expectedRevision()+1,input.advancePaise(),input.creditDue(),input.reason().trim(),u.id());event(id,u.id(),"PAYMENT_REQUEST",event,"Payment terms agreed: INR "+money(input.advancePaise())+" required before production; "+(input.creditDue()==null?"remaining balance before dispatch.":"balance on approved credit until "+input.creditDue()+".")+" "+input.reason().trim());return view(u,id);}
 @Transactional public Map<String,Object> receive(StaffPrincipal u,UUID id,Receipt input){scope(u,id,true);var q=quote(id);current(q,input.quoteId());if(!input.verified())throw new IllegalArgumentException("Confirm receipt of funds");if(input.reference().trim().length()<3)throw new IllegalArgumentException("Payment reference required");if(input.paidOn().isAfter(LocalDate.now(ZoneId.of("Asia/Kolkata"))))throw new IllegalArgumentException("Payment date is in the future");var existing=db.queryForList("select * from payment_receipts where id=?",input.id());if(!existing.isEmpty()){var r=existing.getFirst();if(!id.equals(r.get("enquiry_id"))||!input.quoteId().equals(r.get("quote_id"))||amount(r,"amount_paise")!=input.amountPaise()||!input.method().equals(r.get("method"))||!input.reference().trim().equals(r.get("reference"))||!input.paidOn().toString().equals(r.get("paid_on").toString()))throw conflict("Receipt request identifier was already used with different details");return view(u,id);}if(paid(id)+input.amountPaise()>amount(q,"total_paise"))throw conflict("Payment exceeds the outstanding balance");if(db.queryForObject("select exists(select 1 from payment_receipts where enquiry_id=? and method=? and reference=?)",Boolean.class,id,input.method(),input.reference().trim()))throw conflict("This payment reference is already recorded");db.update("insert into payment_receipts(id,enquiry_id,quote_id,amount_paise,method,reference,paid_on,actor_id) values(?,?,?,?,?,?,?,?)",input.id(),id,input.quoteId(),input.amountPaise(),input.method(),input.reference().trim(),input.paidOn(),u.id());event(id,u.id(),"PAYMENT_RECEIVED",input.id(),"Verified payment received: INR "+money(input.amountPaise())+" by "+input.method()+". Remaining balance: INR "+money(Math.max(0,amount(q,"total_paise")-paid(id)))+". Receipt available in your workspace.");return view(u,id);}
 @Transactional public Map<String,Object> reverse(StaffPrincipal u,UUID id,UUID receipt,Reverse input){scope(u,id,true);if(input.reason().trim().length()<10)throw new IllegalArgumentException("Explain the correction");var r=db.queryForList("select amount_paise from payment_receipts where id=? and enquiry_id=?",receipt,id);if(r.isEmpty())throw new NoSuchElementException();if(db.queryForObject("select exists(select 1 from payment_reversals where receipt_id=?)",Boolean.class,receipt))return view(u,id);long after=paid(id)-amount(r.getFirst(),"amount_paise");var f=db.queryForList("select state from fulfilment_work where enquiry_id=?",id);if(!f.isEmpty()){var q=quote(id);var p=policy(id);if(!valid(q,p)||after<amount(p,"advance_paise"))throw conflict("Correction would invalidate released production payment rules; reconcile with the owner first");if(Set.of("IN_TRANSIT","DELIVERED","COMPLETED").contains(f.getFirst().get("state"))&&after<amount(q,"total_paise")&&!credit(p))throw conflict("Correction would invalidate dispatched payment rules");}UUID event=UUID.randomUUID();db.update("insert into payment_reversals(id,receipt_id,reason,actor_id) values(?,?,?,?)",event,receipt,input.reason().trim(),u.id());event(id,u.id(),"PAYMENT_CORRECTED",event,"Payment receipt corrected: "+input.reason().trim()+". Check your updated balance. This correction is not a bank refund.");return view(u,id);}
 /** Called within fulfilment's enquiry lock; no client-side bypass. */
 public void require(UUID id,UUID quoteId,boolean dispatch){var q=quote(id);current(q,quoteId);var p=policy(id);if(!valid(q,p))throw conflict("Owner must configure payment terms for the current accepted quotation");long received=paid(id),total=amount(q,"total_paise");if(received>total)throw conflict("Reconcile overpayment before proceeding");if(received<amount(p,"advance_paise"))throw conflict("Verified advance payment is required before production");if(dispatch){if(received<total&&!credit(p))throw conflict("Record the remaining balance before dispatch; approved credit must still be valid");if(!db.queryForObject("select exists(select 1 from finance_invoices where enquiry_id=? and quote_id=?)",Boolean.class,id,quoteId))throw conflict("Issue the invoice for the current agreement before dispatch");}}
 @Transactional public Map<String,Object> issue(StaffPrincipal u,UUID id,Issue input){var e=scope(u,id,true);var q=quote(id);current(q,input.quoteId());if(!valid(q,policy(id)))throw conflict("Configure payment terms before issuing the invoice");if(db.queryForObject("select exists(select 1 from quote_versions where enquiry_id=? and state='ISSUED')",Boolean.class,id))throw conflict("Resolve the pending quotation amendment before invoicing");var old=db.queryForList("select id from finance_invoices where quote_id=?",input.quoteId());if(!old.isEmpty())return view(u,id);long number=db.queryForObject("select nextval(pg_get_serial_sequence('finance_invoices','invoice_number'))",Long.class);UUID invoice=UUID.randomUUID();LocalDate date=LocalDate.now(ZoneId.of("Asia/Kolkata"));var snapshot=new LinkedHashMap<String,Object>(q);snapshot.put("customer",e.get("customer_name"));snapshot.put("email",e.get("email"));snapshot.put("policy",policy(id));byte[] bytes=pdf.create(number,date,snapshot);db.update("insert into finance_invoices(id,enquiry_id,quote_id,invoice_number,issued_on,total_paise,snapshot,document_pdf,document_sha256,actor_id) overriding system value values(?,?,?,?,?,?,?::jsonb,?,?,?)",invoice,id,input.quoteId(),number,date,q.get("total_paise"),json.writeValueAsString(snapshot),bytes,sha(bytes),u.id());event(id,u.id(),"INVOICE",invoice,"Invoice INV-"+number+" issued for INR "+money(amount(q,"total_paise"))+". View the attached commercial invoice and your current payment balance in the workspace.");db.update("update mail_outbox set invoice_id=? where enquiry_id=? and kind='INVOICE' and invoice_id is null",invoice,id);return view(u,id);}
 @Transactional(readOnly=true) public byte[] document(StaffPrincipal u,UUID id,UUID invoice){scope(u,id,false);var rows=db.queryForList("select document_pdf,document_sha256 from finance_invoices where id=? and enquiry_id=?",invoice,id);if(rows.isEmpty())throw new NoSuchElementException();var row=rows.getFirst();byte[] bytes=(byte[])row.get("document_pdf");if(!sha(bytes).equals(row.get("document_sha256")))throw new IllegalStateException("Invoice integrity check failed");return bytes;}
 private void event(UUID id,UUID actor,String kind,UUID event,String text){db.update("insert into work_events(id,enquiry_id,actor_id,kind,message) values(?,?,?,?,?)",event,id,actor,kind,text);mail.both(id,kind,event,text);}
 public static String sha(byte[] b){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}
 static String money(long n){return java.math.BigDecimal.valueOf(n,2).toPlainString();}
}
